import click

@click.group()
def cli(): pass

@cli.command()
@click.argument("name")
@click.option("--count", "-c", default=1)
def greet(name, count):
    for _ in range(count):
        click.echo(f"Hello, {name}!")

if __name__ == "__main__":
    cli()
